// Model of %GetOptimizationStatus: a bitmask of tier flags.
// V8's real bits differ in number; we use a small illustrative table.
const BITS = [
  { bit: 0, name: 'isFunction' },
  { bit: 1, name: 'isOptimized' },
  { bit: 2, name: 'isInterpreted' },
  { bit: 3, name: 'isTurboFanned' },
  { bit: 4, name: 'markedForDeopt' },
];
function decode(status) {
  return BITS.filter(b => (status & (1 << b.bit)) !== 0).map(b => b.name);
}

const status = 0b1011; // bits 0,1,3 set
const set = decode(status);
console.log('set=' + set.join(',') + ' optimized=' + set.includes('isOptimized'));
